BEGIN;
DO $$ DECLARE a uuid;b uuid;secretary uuid;outsider uuid;s uuid;c uuid;c2 uuid;c3 uuid;t uuid;r jsonb;again jsonb;j public.delivery_jobs;hold_id uuid;old_id uuid;before_revision integer;legacy uuid;BEGIN
 INSERT INTO public.admin_users(email,password_hash,role,is_active) VALUES('contact-followup-a@example.test','fixture','super_admin',true) RETURNING id INTO a;
 INSERT INTO public.admin_users(email,password_hash,role,is_active) VALUES('contact-followup-b@example.test','fixture','super_admin',true) RETURNING id INTO b;
 INSERT INTO public.admin_users(email,password_hash,role,is_active) VALUES('contact-secretary@example.test','fixture','admin',true) RETURNING id INTO secretary;
 INSERT INTO public.admin_users(email,password_hash,role,is_active) VALUES('contact-outsider@example.test','fixture','team_member',true) RETURNING id INTO outsider;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash) VALUES(a,repeat('58',32)) RETURNING id INTO s;
 INSERT INTO public.team_members(name,role,email,admin_user_id,is_active) VALUES('Fictional secretary','Secretary','contact-secretary@example.test',secretary,true),('Unauthorized title','Secretary','contact-outsider@example.test',outsider,true);
 c:=public.submit_contact('{"name":"Fictional Person","email":"contact-person@example.test","type":"membership","message":"A fictional inquiry for assignment and reply tests."}',repeat('59',32),repeat('5a',32));
 SELECT assigned_task_id INTO t FROM public.contact_submissions WHERE id=c;
 IF t IS NULL OR(SELECT assigned_to_id FROM public.communication_tasks WHERE id=t)<>secretary THEN RAISE EXCEPTION 'Secretary was not assigned';END IF;
 IF public.submit_contact('{"name":"Fictional Person","email":"contact-person@example.test","type":"membership","message":"A fictional inquiry for assignment and reply tests."}',repeat('59',32),repeat('5a',32))<>c OR(SELECT count(*) FROM public.communication_tasks WHERE description LIKE '%'||c||'%')<>1 THEN RAISE EXCEPTION 'Duplicate followup created';END IF;
 UPDATE public.admin_users SET is_active=false WHERE id=secretary;
 c2:=public.submit_contact('{"name":"Second Person","email":"contact-second@example.test","type":"general","message":"A fictional second inquiry for fallback assignment."}',repeat('5b',32),repeat('5c',32));
 c3:=public.submit_contact('{"name":"Third Person","email":"contact-third@example.test","type":"general","message":"A fictional third inquiry for balanced fallback assignment."}',repeat('5d',32),repeat('5e',32));
 IF(SELECT t.assigned_to_id FROM public.contact_submissions x JOIN public.communication_tasks t ON t.id=x.assigned_task_id WHERE x.id=c2) NOT IN(a,b) OR
 (SELECT t.assigned_to_id FROM public.contact_submissions x JOIN public.communication_tasks t ON t.id=x.assigned_task_id WHERE x.id=c2)=(SELECT t.assigned_to_id FROM public.contact_submissions x JOIN public.communication_tasks t ON t.id=x.assigned_task_id WHERE x.id=c3) THEN RAISE EXCEPTION 'Fallback assignment is not balanced across eligible super admins';END IF;
 r:=public.mutate_contact_write(a,s,c,1,'reply','{"body":"Hi, thanks for contacting our chapter. Here is a fictional reply."}',NULL,repeat('5f',32),repeat('60',32),gen_random_uuid());
 IF r->>'action'<>'reply' OR(SELECT status FROM public.contact_submissions WHERE id=c)<>'in_progress' OR(SELECT status FROM public.communication_tasks WHERE id=t)<>'in-progress' THEN RAISE EXCEPTION 'Reply status or task synchronization failed';END IF;
 again:=public.mutate_contact_write(a,s,c,1,'reply','{"body":"Hi, thanks for contacting our chapter. Here is a fictional reply."}',NULL,repeat('5f',32),repeat('60',32),gen_random_uuid());
 IF again<>r OR(SELECT count(*) FROM public.contact_replies WHERE contact_id=c)<>1 THEN RAISE EXCEPTION 'Reply retry duplicated email';END IF;
 SELECT * INTO j FROM public.claim_delivery_jobs(100) WHERE kind='contact_reply' AND payload->>'contactId'=c::text;
 IF j.id IS NULL OR public.prepare_contact_reply(j.id,j.lease_token)->>'email'<>'contact-person@example.test' THEN RAISE EXCEPTION 'Reply recipient not derived from inquiry';END IF;
 IF public.prepare_contact_reply(j.id,gen_random_uuid()) IS NOT NULL THEN RAISE EXCEPTION 'Stale delivery lease accepted';END IF;
 r:=public.contact_inbox(a,s,c,'{}',1);
 IF r->'items'->0->'replies'->0->>'state'<>'queued' OR r->'items'->0->'assignment'->>'taskId'<>t::text THEN RAISE EXCEPTION 'Reply history or assignment missing';END IF;
 PERFORM public.finish_delivery_job(j.id,j.lease_token,true,'fictional-provider-id',NULL);
 UPDATE public.delivery_jobs SET provider_message_id=NULL WHERE id=j.id;
 IF public.contact_inbox(a,s,c,'{}',1)->'items'->0->'replies'->0->>'state'<>'sent' THEN RAISE EXCEPTION 'Accepted email not reflected in history';END IF;
 before_revision:=(SELECT revision FROM public.contact_submissions WHERE id=c);
 PERFORM public.mutate_contact_write(a,s,c,before_revision,'status','{"status":"resolved"}',NULL,repeat('61',32),repeat('62',32),gen_random_uuid());
 IF(SELECT status FROM public.communication_tasks WHERE id=t)<>'completed' THEN RAISE EXCEPTION 'Resolution did not complete followup';END IF;
 UPDATE public.contact_submissions SET resolved_at=now()-interval '200 days' WHERE id=c;
 PERFORM public.claim_contact_upload_cleanup(50);
 IF(SELECT redacted_at FROM public.contact_submissions WHERE id=c) IS NOT NULL THEN RAISE EXCEPTION 'Inquiry erased before 365 days';END IF;
 UPDATE public.contact_submissions SET resolved_at=now()-interval '366 days',retention_hold=true WHERE id=c;
 PERFORM public.claim_contact_upload_cleanup(50);
 IF(SELECT redacted_at FROM public.contact_submissions WHERE id=c) IS NOT NULL THEN RAISE EXCEPTION 'Retention hold ignored';END IF;
 UPDATE public.contact_submissions SET retention_hold=false WHERE id=c;
 PERFORM public.claim_contact_upload_cleanup(50);
 IF(SELECT redacted_at FROM public.contact_submissions WHERE id=c) IS NULL OR(SELECT body FROM public.contact_replies WHERE contact_id=c)<>'' THEN RAISE EXCEPTION '365 day cleanup did not erase inquiry and reply body together';END IF;
 IF public.prepare_contact_reply(j.id,j.lease_token) IS NOT NULL THEN RAISE EXCEPTION 'Redacted inquiry prepared for delivery';END IF;
 INSERT INTO public.contact_submissions(name,email,inquiry_type,message,status,idempotency_key_hash,request_hash) VALUES('Existing fixture','legacy-contact@example.test','general','Existing unanswered contact.','resolved',repeat('65',32),repeat('66',32)) RETURNING id INTO legacy;
 UPDATE public.contact_submissions SET status='new',resolved_at=NULL WHERE id=legacy;
 PERFORM public.mutate_contact_write(a,s,legacy,1,'assign','{}',NULL,repeat('63',32),repeat('64',32),gen_random_uuid());
 IF(SELECT assigned_task_id FROM public.contact_submissions WHERE id=legacy) IS NULL THEN RAISE EXCEPTION 'Existing inquiry could not receive a followup';END IF;
 IF has_table_privilege('authenticated','public.contact_replies','SELECT') OR has_function_privilege('anon','public.prepare_contact_reply(uuid,uuid)','EXECUTE') THEN RAISE EXCEPTION 'Contact reply data exposed';END IF;
END $$;
ROLLBACK;
